<script setup lang="ts">
type Pair = [string, string]
type Actor = 'person' | 'app' | 'model' | 'source'
type Knowledge = 'none' | 'context' | 'weights' | 'index' | 'document'
type Exchange = { from: Actor; to: Actor; title: Pair; script: Pair; explanation: Pair; knowledge: Knowledge; scope: Pair }
const props = withDefaults(defineProps<{locale?: 'nl' | 'en'}>(), {locale:'nl'})
const nl = computed(() => props.locale === 'nl')
const label = (value:Pair) => value[nl.value ? 0 : 1]
const names:Record<Actor,Pair> = {person:['Persoon','Person'], app:['Applicatie','Application'], model:['Taalmodel','Language model'], source:['Zoekdienst en bronnen','Search and sources']}
const knowledgeNames:Record<Knowledge,Pair> = {none:['Geen nieuwe kennisbron','No new knowledge source'],context:['Gesprekscontext','Conversation context'],weights:['Aangeleerde kennis in het model','Learned knowledge in the model'],index:['Externe zoekindex','External search index'],document:['Opgehaalde brondocumenten','Retrieved source documents']}
const research:Exchange[] = [
 {from:'person',to:'app',title:['Vraag stellen','Submit question'],script:['“Wat veranderde dit jaar in het Nederlandse AI-beleid? Wat betekent dat?”','“What changed in Dutch AI policy this year? What does it mean?”'],explanation:['De gebruiker vraagt naar actuele feiten en hun betekenis.','The user asks for current facts and their meaning.'],knowledge:'none',scope:['Alleen de ingevoerde vraag.','Only the submitted question.']},
 {from:'app',to:'model',title:['Context meegeven','Supply context'],script:['Vraag + toepasselijke instructies + relevante gesprekscontext + beschikbare zoektools.','Question + applicable instructions + relevant conversation context + available search tools.'],explanation:['De applicatie bepaalt welke context aan het taalmodel wordt meegegeven.','The application determines which context to pass to the language model.'],knowledge:'context',scope:['Geselecteerde berichten uit dit gesprek; nog geen actuele webbron.','Selected conversation messages; no current web source yet.']},
 {from:'model',to:'model',title:['Vraag duiden','Interpret question'],script:['Voorbeeld van zichtbare toelichting: “Welke besluiten, welke periode en welke gevolgen bedoelt de vraag?”','Illustrative visible note: “Which decisions, time period and consequences does the question concern?”'],explanation:['Het model herkent deelvragen met aangeleerde taal- en wereldpatronen. Dit is geen afschrift van interne gedachten.','The model identifies subquestions using learned language and world patterns. This is not a transcript of internal thoughts.'],knowledge:'weights',scope:['Aangeleerde patronen en de meegegeven context; geen verifieerbare actuele bron.','Learned patterns and supplied context; no verifiable current source.']},
 {from:'model',to:'app',title:['Aanpak kiezen','Choose approach'],script:['Voorbeeld van zichtbare toelichting: “Zoek officiële besluiten, controleer de datum en lees de relevante tekst voordat ik concludeer.”','Illustrative visible note: “Find official decisions, check dates and read relevant passages before drawing conclusions.”'],explanation:['Het model kan de taak opdelen en een volgende toolactie kiezen. De aanpak kan veranderen na nieuwe informatie; een volledig vooraf uitgeschreven plan is niet verplicht.','The model can break down the task and select a next tool action. The approach can change with new information; a complete advance plan is not required.'],knowledge:'weights',scope:['Vraag, instructies en beschrijvingen van tools; de behoefte aan externe kennis is vastgesteld.','Question, instructions and tool descriptions; a need for external knowledge is identified.']},
 {from:'app',to:'source',title:['Gericht zoeken','Targeted search'],script:['Zoek: “Nederland AI beleid officiële besluiten 2026” in overheidsbronnen.','Search: “Netherlands AI policy official decisions 2026” in government sources.'],explanation:['Het model heeft een gestructureerde zoekactie aangevraagd. De applicatie voert die uit; een zoekdienst selecteert en rangschikt vindbare informatie.','The model requested a structured search. The application executes it; a search service selects and ranks discoverable information.'],knowledge:'index',scope:['Externe index, afgebakend naar onderwerp, datum en bronsoort. Dit is een deel van de kennislaag uit het artikel.','External index, scoped by topic, date and source type. This is part of the knowledge layer examined in the essay.']},
 {from:'source',to:'app',title:['Resultaten terug','Results returned'],script:['Zoekresultaten met titels, datums, links en fragmenten; eventueel worden brondocumenten geopend.','Search results with titles, dates, links and snippets; source documents may also be opened.'],explanation:['Deze informatie komt van buiten het model. Een zoekresultaat is nog geen gecontroleerde bewering.','This information comes from outside the model. A search result is not yet a verified claim.'],knowledge:'index',scope:['Een selectie uit de zoekindex, nooit het hele web.','A selection from the search index, never the entire web.']},
 {from:'app',to:'model',title:['Bronnen meegeven','Supply sources'],script:['Tekstfragmenten met datum en herkomst worden als nieuwe context aan het model gegeven.','Passages with dates and provenance are added as new context for the model.'],explanation:['Het model ziet wat de applicatie in de beschikbare context opneemt; bronmetadata helpt herkomst controleren, niet de waarheid bewijzen.','The model sees what the application includes in its available context; source metadata supports provenance checks, not proof of truth.'],knowledge:'document',scope:['Geselecteerde fragmenten of documenten met eventuele identiteit, versie en herkomst.','Selected passages or documents with identity, version and provenance where available.']},
 {from:'model',to:'model',title:['Controleren en herhalen','Review and repeat'],script:['Voorbeeld van zichtbare toelichting: “Kloppen data en inhoud? Bij een ontbrekend deel zoek ik opnieuw of open ik een bron.”','Illustrative visible note: “Do dates and contents agree? I can search again or open a source for a missing part.”'],explanation:['Het model vergelijkt de aangereikte bronnen en kan een nieuwe zoek- of leesactie vragen.','The model compares supplied sources and may request another search or reading action.'],knowledge:'document',scope:['Alleen documenten die in de context zijn opgenomen, plus aangeleerde patronen.','Only documents included in context, plus learned patterns.']},
 {from:'model',to:'app',title:['Antwoord schrijven','Compose answer'],script:['Het model onderscheidt in het antwoord vastgestelde feiten, interpretatie en onzekerheid en koppelt waar mogelijk bronnen.','The model distinguishes facts, interpretation and uncertainty in the answer and cites sources where possible.'],explanation:['Het antwoord gebruikt de vraag, instructies en beschikbare context. Het model heeft geen directe toegang tot elke bron op internet.','The answer uses the question, instructions and available context. The model does not have direct access to every source on the internet.'],knowledge:'document',scope:['De gekozen externe informatie; die selectie is mogelijk onvolledig.','Selected external information; this selection may be incomplete.']},
 {from:'app',to:'person',title:['Antwoord tonen','Show answer'],script:['De persoon ontvangt het antwoord en kan bronnen openen of doorvragen.','The person receives the answer and can open sources or ask a follow-up.'],explanation:['De applicatie presenteert de uitvoer en eventuele bronlinks.','The application presents the output and any source links.'],knowledge:'none',scope:['Het gepresenteerde antwoord en de eventueel getoonde bronnen.','The displayed answer and any sources shown.']}
]
const direct:Exchange[] = [
 {from:'person',to:'app',title:['Vraag stellen','Submit question'],script:['“Waarom is de lucht blauw?”','“Why is the sky blue?”'],explanation:['Een vraag om een algemene uitleg.','A request for a general explanation.'],knowledge:'none',scope:['De ingevoerde vraag.','The submitted question.']},
 {from:'app',to:'model',title:['Context meegeven','Supply context'],script:['Vraag + instructies + relevante gesprekscontext.','Question + instructions + relevant conversation context.'],explanation:['De applicatie stelt de invoer samen.','The application assembles the input.'],knowledge:'context',scope:['Vraag en geselecteerde gesprekscontext.','Question and selected conversation context.']},
 {from:'model',to:'model',title:['Vraag duiden','Interpret question'],script:['Voorbeeld van zichtbare toelichting: “Dit vraagt om uitleg over lichtverstrooiing; ik heb geen actuele zoekactie nodig.”','Illustrative visible note: “This calls for an explanation of light scattering; no current search is needed.”'],explanation:['Het model gebruikt aangeleerde patronen, zonder externe bron op te halen.','The model uses learned patterns without retrieving an external source.'],knowledge:'weights',scope:['Informatie in modelgewichten; geen afzonderlijk opvraagbare bron.','Information in model weights; no individually retrievable source.']},
 {from:'model',to:'app',title:['Uitleg schrijven','Write explanation'],script:['Het model formuleert een beknopte uitleg van verstrooiing van zonlicht.','The model composes a brief explanation of sunlight scattering.'],explanation:['Ook een rechtstreeks antwoord kan onjuist zijn; hier zijn geen actuele bronnen geraadpleegd.','A direct answer may still be wrong; no current sources were consulted.'],knowledge:'weights',scope:['Aangeleerde informatie plus de huidige context.','Learned information plus current context.']},
 {from:'app',to:'person',title:['Antwoord tonen','Show answer'],script:['De persoon ontvangt de uitleg en kan doorvragen.','The person receives the explanation and can follow up.'],explanation:['De applicatie toont het antwoord.','The application displays the answer.'],knowledge:'none',scope:['Het antwoord zonder nieuw opgehaalde bron.','The answer without a newly retrieved source.']}
]
const scenario = ref<'research'|'direct'>('research')
const current = ref(0)
const playing = ref(false)
let timer:ReturnType<typeof setInterval>|undefined
const steps = computed(() => scenario.value === 'research' ? research : direct)
const step = computed(() => steps.value[current.value]!)
const actors:Actor[] = ['person','app','model','source']
const direction = computed(() => `${label(names[step.value.from])} → ${label(names[step.value.to])}`)
function stop(){if(timer) clearInterval(timer);timer=undefined;playing.value=false}
function select(index:number){stop();current.value=index}
function choose(value:'research'|'direct'){stop();scenario.value=value;current.value=0}
function advance(){if(current.value>=steps.value.length-1){stop();return}current.value++}
function play(){if(playing.value){stop();return}if(current.value===steps.value.length-1)current.value=0;playing.value=true;timer=setInterval(advance,2300)}
onUnmounted(stop)
</script>

<template>
 <section class="question-flow" :lang="locale" :aria-label="nl?'Van vraag naar AI-antwoord':'From question to AI answer'">
  <header class="flow-head"><div><p class="eyebrow">{{nl?'Een gesprek tussen vier spelers':'An exchange between four actors'}}</p><h3>{{nl?'Van vraag naar antwoord':'From question to answer'}}</h3></div><div class="scenarios" role="group" :aria-label="nl?'Type vraag':'Question type'"><button type="button" :aria-pressed="scenario==='research'" @click="choose('research')">{{nl?'Actuele vraag':'Current question'}}</button><button type="button" :aria-pressed="scenario==='direct'" @click="choose('direct')">{{nl?'Algemene vraag':'General question'}}</button></div></header>
  <div class="stage" :aria-label="nl?'Vaste onderdelen van het systeem':'Fixed parts of the system'"><div v-for="actor in actors" :key="actor" :class="['actor',`flow-${actor}`,{sending:step.from===actor,receiving:step.to===actor&&step.from!==actor}]"><span class="actor-icon" aria-hidden="true">{{({person:'◉',app:'▦',model:'✧',source:'▤'} as Record<Actor,string>)[actor]}}</span><strong>{{label(names[actor])}}</strong><small v-if="actor==='person'">{{nl?'Vraagt en ontvangt':'Asks and receives'}}</small><small v-else-if="actor==='app'">{{nl?'Stelt context samen; voert acties uit':'Assembles context; runs actions'}}</small><small v-else-if="actor==='model'">{{nl?'Interpreteert, kiest en formuleert':'Interprets, selects and composes'}}</small><small v-else>{{nl?'Index, zoektool en publicaties':'Index, search tool and publications'}}</small></div></div>
  <div class="exchange" aria-live="polite" aria-atomic="true"><span class="exchange-pair">{{direction}}</span><span class="signal" aria-hidden="true"><i :key="`${scenario}-${current}`" /></span><strong>{{label(step.title)}}</strong></div>
  <div class="script-head"><h4>{{nl?'Wat gebeurt er?':'What happens?'}}</h4><span>{{current+1}} / {{steps.length}}</span></div>
  <label class="mobile-step">{{nl?'Kies een stap':'Choose a step'}}<select :value="current" @change="select(Number(($event.target as HTMLSelectElement).value))"><option v-for="(entry,index) in steps" :key="index" :value="index">{{index+1}}. {{label(entry.title)}}</option></select></label>
  <div class="script-layout"><nav class="script-index" :aria-label="nl?'Kies stap':'Select step'"><button v-for="(entry,index) in steps" :key="index" type="button" :class="{active:index===current,done:index<current}" :aria-current="index===current?'step':undefined" @click="select(index)"><span>{{index+1}}</span>{{label(entry.title)}}</button></nav><div class="script-content" aria-live="polite" aria-atomic="true"><p class="script-speaker">{{direction}}</p><p class="script-line">{{label(step.script)}}</p><p class="script-explanation">{{label(step.explanation)}}</p><div :class="['knowledge',{external:step.knowledge==='index'||step.knowledge==='document'}]"><strong>{{nl?'Kennis in deze stap':'Knowledge in this step'}}: {{label(knowledgeNames[step.knowledge])}}</strong><span>{{label(step.scope)}}</span></div></div></div>
  <div class="playback"><button type="button" @click="play">{{playing?(nl?'Pauze':'Pause'):(nl?'Speel af':'Play')}}</button><button type="button" :disabled="current===0" @click="select(current-1)">{{nl?'Vorige':'Previous'}}</button><button type="button" :disabled="current===steps.length-1" @click="select(current+1)">{{nl?'Volgende':'Next'}}</button></div>
  <details class="accuracy"><summary>{{nl?'Hoe letterlijk is deze weergave?':'How literal is this view?'}}</summary><p>{{nl?'De werknotities zijn didactische voorbeelden van mogelijke zichtbare toelichting, geen uitgelezen interne gedachtegang. Niet ieder product maakt een expliciet plan of gebruikt dezelfde context en hulpmiddelen. Een zoekindex toont slechts een selectie; ook bronherkomst bewijst niet dat een bewering waar is.':'Work notes are teaching examples of possible visible commentary, not a readout of private reasoning. Products do not all make an explicit plan or use the same context and tools. A search index exposes only a selection; provenance alone does not establish truth.'}}</p></details>
 </section>
</template>

<style scoped>
.question-flow{--ink:#183b34;--muted:#546b64;box-sizing:border-box;width:100%;min-width:0;margin:1.4rem 0;padding:1rem;border:1px solid #c9d7d0;border-radius:14px;background:#f7f9f6;color:var(--ink);font:400 .8rem/1.42 system-ui,sans-serif}.question-flow *{box-sizing:border-box}.flow-head{display:flex;justify-content:space-between;align-items:end;gap:.9rem}.flow-head h3{margin:.12rem 0 0;font:700 clamp(1.08rem,2vw,1.5rem)/1.2 system-ui,sans-serif}.eyebrow{margin:0!important;color:var(--muted);font-size:.61rem;letter-spacing:.07em;text-transform:uppercase}.question-flow button{font:600 .72rem/1.25 system-ui,sans-serif;cursor:pointer}.scenarios{display:flex;gap:.3rem;flex-wrap:wrap}.scenarios button,.playback button{border:1px solid #becdc5;border-radius:7px;background:#fff;color:var(--ink);padding:.44rem .65rem}.scenarios button[aria-pressed=true],.playback button:first-child{border-color:var(--ink);background:var(--ink);color:#fff}.stage{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:.45rem;margin:1rem 0 .5rem}.actor{display:flex;flex-direction:column;gap:.12rem;min-width:0;min-height:102px;padding:.7rem;border:1px solid #cbd9d2;border-radius:10px;background:#fff;transition:background .3s,border-color .3s,box-shadow .3s}.actor-icon{font-size:1.15rem;line-height:1;color:#567a70}.actor strong{font-size:.75rem;line-height:1.2;overflow-wrap:anywhere}.actor small{font-size:.6rem;line-height:1.25;color:var(--muted)}.actor.sending{border-color:#bb754e;background:#fdf4eb;box-shadow:inset 0 3px #bb754e}.actor.receiving{border-color:#397b70;background:#ebf5f0;box-shadow:inset 0 3px #397b70}.actor.sending.receiving{background:#f1eae1}.exchange{display:flex;align-items:center;gap:.55rem;min-height:43px;padding:.45rem .7rem;border-radius:9px;background:#e7efe9}.exchange-pair{flex:0 1 auto;font-size:.67rem;font-weight:700}.exchange strong{margin-left:auto;font-size:.7rem;text-align:right}.signal{position:relative;flex:1 1 55px;max-width:140px;height:2px;background:#7b9c90}.signal:after{content:'›';position:absolute;right:-.2rem;top:-.78rem;font-size:1.2rem;color:#456c5e}.signal i{position:absolute;top:-4px;left:0;width:10px;height:10px;border-radius:50%;background:#ae623e;animation:signal 1.3s ease-in-out both}@keyframes signal{from{left:0}to{left:calc(100% - 10px)}}.script-head{display:flex;align-items:baseline;justify-content:space-between;margin:1rem 0 .4rem}.script-head h4{margin:0;font:700 .85rem/1.3 system-ui,sans-serif}.script-head span{color:var(--muted);font-size:.68rem}.mobile-step{display:none}.script-layout{display:grid;grid-template-columns:minmax(170px,32%) minmax(0,1fr);gap:.7rem}.script-index{display:grid;gap:.15rem;align-content:start}.script-index button{display:flex;align-items:center;gap:.5rem;width:100%;min-width:0;padding:.38rem .45rem;border:1px solid transparent;border-radius:6px;background:transparent;color:var(--ink);text-align:left}.script-index button.active{border-color:#8ca99b;background:#e0ece5}.script-index button.done{color:var(--muted)}.script-index button span{display:grid;place-items:center;flex:0 0 1.24rem;width:1.24rem;height:1.24rem;border-radius:50%;background:#dce7df;font-size:.62rem}.script-index button.active span{background:var(--ink);color:#fff}.script-content{align-self:start;min-width:0;padding:.85rem 1rem;border:1px solid #d3dfd8;border-radius:9px;background:#fff}.script-content p{margin:0 0 .55rem}.script-speaker{color:var(--muted);font-size:.62rem;font-weight:700;text-transform:uppercase;letter-spacing:.04em}.script-line{font-size:.82rem;font-weight:650}.script-explanation{font-size:.7rem;color:var(--muted)}.knowledge{display:grid;gap:.2rem;margin-top:.7rem;padding:.6rem;border-left:3px solid #7c958b;background:#f0f4f1;font-size:.67rem}.knowledge.external{border-color:#b7683e;background:#fbf1e8}.knowledge span{color:var(--muted)}.playback{display:flex;gap:.35rem;flex-wrap:wrap;margin-top:.8rem}.playback button:disabled{opacity:.45;cursor:default}.accuracy{margin-top:.9rem;border-top:1px solid #d6e0da;padding-top:.65rem;font-size:.67rem}.accuracy summary{cursor:pointer;font-weight:700}.accuracy p{margin:.45rem 0 0!important;color:var(--muted)}@media(max-width:660px){.flow-head{align-items:start;flex-direction:column}.stage{grid-template-columns:repeat(2,minmax(0,1fr))}.actor{min-height:75px;padding:.55rem}.actor small{font-size:.57rem}.script-layout{display:block}.script-index{display:none}.mobile-step{display:grid;gap:.25rem;margin:0 0 .6rem;color:var(--muted);font-size:.65rem}.mobile-step select{max-width:100%;padding:.5rem;border:1px solid #aebfb5;border-radius:7px;background:#fff;color:var(--ink);font:600 .75rem system-ui,sans-serif}.script-content{min-height:210px}.exchange{flex-wrap:wrap}.exchange-pair{flex-basis:100%}.exchange strong{margin-left:0;text-align:left}.signal{max-width:100px}.scenarios button{font-size:.68rem}}@media(prefers-reduced-motion:reduce){.signal i{animation:none;left:calc(100% - 10px)}.actor{transition:none}}
</style>
